"""Build a read-only-art browser layer preview; never writes image pixels or game files."""
import base64,hashlib,json,pathlib
R=pathlib.Path('D:/AI项目/水浒/开发工程');E=pathlib.Path(__file__).parent;P=E/'browser_preview';P.mkdir(exist_ok=False)
raw=json.loads((R/'assets/characters/tribute_cart_wheel_layers_20261018/prompt_set.json').read_text('utf-8'))
layout=json.loads((R/'assets/characters/tribute_cart_wheel_layers_20261018/component_layout.json').read_text('utf-8'))
rows={'original':raw['original_production_cart']}|{x['key']:x for x in raw['sources']}
urls={}
for key,row in rows.items():
 data=(R/row['path']).read_bytes();assert hashlib.sha256(data).hexdigest()==row['sha256'];urls[key]='data:image/png;base64,'+base64.b64encode(data).decode()
html='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><title>江州车分层配准 · 独立预览</title>
<style>body{margin:0;background:#23221f;color:#eee9dc;font:15px system-ui,sans-serif}main{max-width:1440px;margin:0 auto;padding:20px}h1{font-size:23px;margin:0 0 8px}.note{color:#d8c6a5;margin-bottom:18px}.controls{display:flex;gap:22px;align-items:center;flex-wrap:wrap;padding:14px;background:#34322d;border-radius:9px}select,button{font:inherit;color:#eee9dc;background:#48443a;border:1px solid #746b56;border-radius:5px;padding:6px 12px}label{display:flex;gap:9px;align-items:center}input[type=range]{width:150px}canvas{display:block;width:100%;height:auto;background:#292824;border-radius:8px;margin-top:16px}pre{font-size:12px;line-height:1.6;color:#bfb9aa;white-space:pre-wrap}.status{color:#dfb370}output{font-variant-numeric:tabular-nums;min-width:40px}</style>
<main><h1>江州车：车身与独立木轮配准</h1><div class="note">独立素材预览，尚未接入游戏。静态合成不代表轮转、原生引擎或剧情数量验收。</div>
<div class="controls"><label>方向<select id="direction"><option value="se">东南 SE</option><option value="sw">西南 SW</option><option value="ne">东北 NE</option><option value="nw">西北 NW</option></select></label><label>轮高缩放<input id="scale" type="range" min="0.4" max="1" step="0.001"><output id="scale_value"></output></label><label>横向微调<input id="dx" type="range" min="-60" max="60" step="1" value="0"><output id="dx_value">0</output></label><label>纵向微调<input id="dy" type="range" min="-60" max="60" step="1" value="0"><output id="dy_value">0</output></label><label><input id="guides" type="checkbox">显示轮毂/原轮底</label><button id="reset">重置当前方向</button></div>
<canvas id="stage" width="1440" height="820" aria-label="左侧旧生产车，右侧去轮车身与独立轮静态合成"></canvas><div id="status" class="status">正在载入原字节素材…</div><pre id="measurements"></pre></main>
<script>const layout=__LAYOUT__;const urls=__URLS__;const files=__FILES__;const state={};for(const d of Object.keys(layout.directions))state[d]={scale:layout.directions[d].wheel_uniform_scale,dx:0,dy:0};const $=id=>document.getElementById(id);const ctx=$('stage').getContext('2d');const images={};let ready=false;
function direction(){return $('direction').value}function sync(){const s=state[direction()];for(const k of ['scale','dx','dy']){$(k).value=s[k];$(k+'_value').value=k==='scale'?s[k].toFixed(3):s[k]}draw()}
function draw(){if(!ready)return;const d=direction(),row=layout.directions[d],pose=row.original_cart_pose,s=state[d],unit=400/pose.virtual_canvas_reference,reg=pose.region,center=[reg[0]+reg[2]/2,reg[1]+reg[3]/2];ctx.fillStyle='#292824';ctx.fillRect(0,0,1440,820);ctx.fillStyle='#eee9dc';ctx.font='bold 24px system-ui';ctx.fillText(d.toUpperCase()+' · 旧生产车',40,55);ctx.fillText(d.toUpperCase()+' · 分层候选',760,55);ctx.strokeStyle='#514b3f';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(720,85);ctx.lineTo(720,760);ctx.stroke();
function point(panel,p){return [360+panel*720+(p[0]-center[0])*unit,430+(p[1]-center[1])*unit]}function paint(panel,img,region,sc=1,tr=[0,0]){const p=point(panel,[region[0]*sc+tr[0],region[1]*sc+tr[1]]);ctx.drawImage(img,...region,...p,region[2]*sc*unit,region[3]*sc*unit)}
paint(0,images.original,reg);paint(1,images.cart_body,row.body_region);const h=row.new_wheel_hub_estimate,target=row.original_hub_estimate,tr=[target[0]+s.dx-h[0]*s.scale,target[1]+s.dy-h[1]*s.scale];paint(1,images.wheel_only,row.wheel_region,s.scale,tr);
if($('guides').checked){for(const panel of [0,1]){for(const [p,color] of [[row.original_hub_estimate,'#ffad55'],[row.original_wheel_ground_contact,'#7fcae4']]){const q=point(panel,p);ctx.strokeStyle=color;ctx.beginPath();ctx.moveTo(q[0]-8,q[1]);ctx.lineTo(q[0]+8,q[1]);ctx.moveTo(q[0],q[1]-8);ctx.lineTo(q[0],q[1]+8);ctx.stroke()}}}
$('measurements').textContent=JSON.stringify({direction:d,wheel_uniform_scale:s.scale,wheel_translation_original_native:tr,hub_offset_native:[s.dx,s.dy],source_sha256:files,scope:'浏览器静态绘制，仅供配准判断；原始PNG未改。无旋转/原生/实际游戏通过。'},null,2)}
for(const k of ['scale','dx','dy'])$(k).addEventListener('input',()=>{state[direction()][k]=Number($(k).value);sync()});$('direction').addEventListener('change',sync);$('guides').addEventListener('change',draw);$('reset').addEventListener('click',()=>{state[direction()]={scale:layout.directions[direction()].wheel_uniform_scale,dx:0,dy:0};sync()});
Promise.all(Object.entries(urls).map(([key,url])=>new Promise((resolve,reject)=>{const im=new Image();im.onload=()=>{images[key]=im;resolve()};im.onerror=reject;im.src=url}))).then(()=>{ready=true;$('status').textContent='已载入三份1254×1254原字节素材。轮轴位置为人工近似点，待直接看图与Godot后验。';sync()}).catch(e=>{$('status').textContent='素材载入失败：'+e});</script></html>'''
html=html.replace('__LAYOUT__',json.dumps(layout,ensure_ascii=False)).replace('__URLS__',json.dumps(urls)).replace('__FILES__',json.dumps({k:v['sha256'] for k,v in rows.items()}))
(P/'index.html').write_bytes(html.encode());(E/'browser_preview_binding.json').write_text(json.dumps({'path':str(P/'index.html'),'sha256':hashlib.sha256((P/'index.html').read_bytes()).hexdigest(),'art_sources':rows,'runtime_adopted':False,'native_complete':False,'bitmap_files_modified':False},ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
print(json.dumps({'preview':str(P/'index.html'),'embedded_original_pngs':3,'bitmap_files_modified':False,'native_complete':False}))
